    'مقدرناش نحسب الاستخدام، جرّب تاني.' => 'We could not calculate usage, try again.',
    'مقدرناش نحسب الاستخدام، جرّب تاني' => 'We could not calculate usage, try again',
    'الأرقام من DataForSEO حسب البلد واللغة. — معناها مش مقاس (not measured). بيانات البحث بتتخزن 30 يوم، وفحص الترتيب مرة يوميًا. البحث والفحص المدفوع بيتحسبوا من حصة الباقة وبعدها المحفظة' => 'Numbers come from DataForSEO by country and language. — means not measured. Search data is stored for 30 days, and rankings are checked once a day. Paid searches and checks use your plan allowance first, then your wallet',
    'بعض الكلمات فيها تعليقات تحليل وليست عبارة بحث صافية. راجع العبارة المقترحة ثم نقِّ الكلمات غير المقاسة. التنقية مجانية ولا تبدأ بحثًا أو قياس ترتيب، والسجلات المقاسة لا تُعدَّل' => 'Some keywords include analysis notes and are not clean search phrases. Review the suggested phrase, then clean the unmeasured keywords. Cleaning is free, starts no search or rank check, and measured records are not changed',
