    'تصحيح السوق المختار إذا لم يبدأ قياسه' => 'Correct the selected market if it has not been measured yet',
    'بلد الجمهور يختلف عن بلد نشاطك. لو باقتك تسمح بسوق واحد، يمكن تصحيح السوق الافتراضي قبل وجود قياسات أو إعدادات مرتبطة به؛ السجلات المقاسة لا نعيد تسميتها' => 'The audience country is different from your business country. If your plan allows one market, the default market can be corrected before it has measurements or linked settings; measured records are never renamed',
    'خلّي السوق المختار رئيسي' => 'Make the selected market the main one',
    'كلمة تتابعها' => 'Keyword to track',
    'إضافة للمتابعة' => 'Track it',
    'قياس الكلمات المحفوظة بميزانية واضحة' => 'Measure saved keywords with a clear budget',
    'نبدأ بما يصل إلى خمس كلمات تحتاج بيانات حديثة في السوق المختار. إذا لم تضف كلمات بعد، نبحث موقعك لدى المزود لاستخراج أول خمس كلمات حقيقية، دون اختلاق بيانات. عرض الاستخدام مجاني؛ تأكيد القياس يستهلك حصة SEO ثم المحفظة حتى السقف الذي تحدده' => 'We start with up to five keywords that need fresh data in the selected market. If you have not added keywords yet, we look up your website with the provider to get its first five real keywords, without inventing data. Viewing usage is free; confirming the measurement uses SEO allowance, then the wallet up to the cap you set',
