    'الكلمات المحفوظة لها بيانات حديثة، أو لا توجد كلمات تحتاج قياسًا. الأرقام غير المتاحة تظل غير مقاسة' => 'Saved keywords have fresh data, or no keywords need measuring. Unavailable numbers stay unmeasured',
