    'راجع نتيجة المقارنة' => 'Review the comparison result',
    'سترى ما اختلف، ومصدره، والقيمة في Google والقيمة الموجودة في المصدر. البيانات التي لم نتمكن من قراءتها تبقى غير معروفة' => 'You will see what differs, its source, the value in Google and the value in the source. Data we could not read stays unknown',
    'قياس ترتيب الخرائط — اختياري ومدفوع' => 'Map ranking measurement — optional and paid',
    'هذا قياس إضافي حول موقع النشاط المؤكد، وليس شرطًا لمقارنة البيانات. شبكة' => 'This is an extra measurement around the confirmed business location, not a requirement for data comparison. A grid of',
    'لكلمتين أو ثلاث تستخدم 50–75 طلب قياس من حصة SEO ثم المحفظة وفق الحدود الحالية. حد الشبكات الشهري مشترك بين مواقع الحساب' => 'for two or three keywords uses 50–75 measurement requests from your SEO allowance, then the wallet within the current limits. The monthly grid limit is shared across the account\'s websites',
