    'اللغات والفهرسة' => 'Languages and indexing',
    'الترجمات مسودات أولًا. أكّد صحة المحتوى الأصلي، راجع كل النصوص والادعاءات ثم انشر. الأرقام والأسعار وبيانات التواصل لا تُترجم آليًا. تغيير الأصل يتطلب مراجعة الترجمة مجددًا' => 'Translations are drafts first. Confirm the original content is correct, review all texts and claims, then publish. Numbers, prices and contact details are not machine-translated. Changing the original requires reviewing the translation again',
    'موقع المنشئ' => 'Builder website',
    'تحميل المحتوى' => 'Load content',
