    'اعتماد ونشر اللغة' => 'Approve and publish the language',
    'السماح بإرسال خريطة الموقع' => 'Allow sitemap submission',
    'اختياري: الربط المعتاد للقراءة فقط. إعادة الربط هنا تطلب webmasters من Google للسماح بإرسال الخرائط. اختر الموقع المؤكد نفسه بعد موافقة Google. لا يتم اعتبار إرسال الخريطة ضمانًا للفهرسة' => 'Optional: the usual connection is read-only. Reconnecting here requests webmasters access from Google to allow sitemap submission. Choose the same verified site after Google\'s approval. Submitting a sitemap is not a guarantee of indexing',
