    'انسخ الكود وحطه في أي صفحة في موقعك. بيعرض المتوسط وأحدث تقييمات 4 و5 نجوم وبيتحدث لوحده' => 'Copy the code and paste it on any page of your website. It shows your average rating and latest 4–5★ reviews, and updates automatically',
