    'تدقيق SEO المحلي بيقرا بيانات ملف نشاطك من Google، والمزامنة مع Google لسه متوقفة. هيشتغل لوحده أول ما المزامنة ترجع.' => 'The local SEO audit reads your Business Profile data from Google, and Google sync is still paused. It will work automatically once sync resumes.',
    'تدقيق SEO المحلي بيقرا بيانات ملف نشاطك من Google، والمزامنة مع Google لسه متوقفة. هيشتغل لوحده أول ما المزامنة ترجع' => 'The local SEO audit reads your Business Profile data from Google, and Google sync is still paused. It will work automatically once sync resumes',
    'تقييم سلبي جديد على' => 'New negative review on',
    'مش محتاج مفاتيح: كل حجز بيتبلّغ أوتوماتيك لبيكسل صاحب الحملة بربط Meta بتاعه هو. سيب الخانات دي فاضية.' => 'No keys needed: each booking is reported automatically to the campaign owner\'s own pixel through their Meta connection. Leave these fields empty.',
    'مش محتاج مفاتيح: كل حجز بيتبلّغ أوتوماتيك لبيكسل صاحب الحملة بربط Meta بتاعه هو. سيب الخانات دي فاضية' => 'No keys needed: each booking is reported automatically to the campaign owner\'s own pixel through their Meta connection. Leave these fields empty',
    'Google: بعض التقييمات ماتحفظتش، والسبب اتسجل في سجل الأخطاء' => 'Google: some reviews could not be saved; the reason was recorded in the error log',
    'مفتاح منفصل عن Google OAuth فوق - لازم يفعّل عليه Maps JavaScript API و Places API و Geocoding API من نفس مشروع Google Cloud. قيّده بالـ APIs دي بس (API restrictions)، وسيب Application restrictions على None: السيرفر بيستخدمه كمان لـ Places وGeocoding، وقيد HTTP referrers بيخلّي جوجل يرفض طلبات السيرفر. نفس المفتاح ده بيشغّل خريطة اختيار موقع النشاط في صفحة منشورات GBP، وكمان بيُستخدم لاكتشاف منافسين حقيقيين عبر Google Places في ذكاء المنافسين.' => 'A separate key from the Google OAuth above. Enable Maps JavaScript API, Places API and Geocoding API on it from the same Google Cloud project. Restrict it to these APIs only (API restrictions) and leave Application restrictions on None: the server also uses it for Places and Geocoding, and an HTTP referrers restriction makes Google reject server requests. The same key powers the business location map on the GBP posts page and is used to discover real competitors via Google Places in Competitor Intelligence.',
    'مفتاح منفصل عن Google OAuth فوق - لازم يفعّل عليه Maps JavaScript API و Places API و Geocoding API من نفس مشروع Google Cloud. قيّده بالـ APIs دي بس (API restrictions)، وسيب Application restrictions على None: السيرفر بيستخدمه كمان لـ Places وGeocoding، وقيد HTTP referrers بيخلّي جوجل يرفض طلبات السيرفر. نفس المفتاح ده بيشغّل خريطة اختيار موقع النشاط في صفحة منشورات GBP، وكمان بيُستخدم لاكتشاف منافسين حقيقيين عبر Google Places في ذكاء المنافسين' => 'A separate key from the Google OAuth above. Enable Maps JavaScript API, Places API and Geocoding API on it from the same Google Cloud project. Restrict it to these APIs only (API restrictions) and leave Application restrictions on None: the server also uses it for Places and Geocoding, and an HTTP referrers restriction makes Google reject server requests. The same key powers the business location map on the GBP posts page and is used to discover real competitors via Google Places in Competitor Intelligence',
