    'ملف robots.txt مانع جوجل من الصفحة دي' => 'robots.txt blocks Google from this page',
    'افتح robots.txt وشيل سطر Disallow اللي بيمنعها، وبعدين اطلب فهرسة من Search Console > فحص الرابط.' => 'Remove the Disallow rule in robots.txt, then request indexing in Search Console > URL Inspection.',
    'افتح robots.txt وشيل سطر Disallow اللي بيمنعها، وبعدين اطلب فهرسة من Search Console > فحص الرابط' => 'Remove the Disallow rule in robots.txt, then request indexing in Search Console > URL Inspection',
    'الصفحة عليها noindex فجوجل مش هيظهرها' => 'The page has noindex, so Google will not show it',
    'في Yoast/RankMath افتح الصفحة > Advanced وخلي "Allow search engines" = Yes، أو شيل noindex من الثيم.' => 'In Yoast/RankMath open the page > Advanced and allow search engines, or remove noindex from the theme.',
    'في Yoast/RankMath افتح الصفحة > Advanced وخلي "Allow search engines" = Yes، أو شيل noindex من الثيم' => 'In Yoast/RankMath open the page > Advanced and allow search engines, or remove noindex from the theme',
    'جوجل اختار صفحة تانية كنسخة أساسية بدل دي (محتوى مكرر أو شبه مكرر)' => 'Google chose a different canonical page (duplicate or near-duplicate content)',
    'جوجل اختار صفحة تانية كنسخة أساسية بدل دي (محتوى مكرر أو شبه مكرر' => 'Google chose a different canonical page (duplicate or near-duplicate content)',
    'خلي محتوى الصفحة مختلف وأوضح (برنامج الرحلة، الأسعار، الصور الخاصة بيها)، أو لو هي نسخة فعلًا وجّهها للصفحة الأساسية.' => 'Make the content clearly unique (itinerary, prices, own photos), or redirect it to the main page if it is a real duplicate.',
    'خلي محتوى الصفحة مختلف وأوضح (برنامج الرحلة، الأسعار، الصور الخاصة بيها)، أو لو هي نسخة فعلًا وجّهها للصفحة الأساسية' => 'Make the content clearly unique (itinerary, prices, own photos), or redirect it to the main page if it is a real duplicate',
    'جوجل زار الصفحة وقرر مايفهرسهاش (غالبًا المحتوى ضعيف أو قصير)' => 'Google crawled the page but did not index it (usually thin content)',
    'جوجل زار الصفحة وقرر مايفهرسهاش (غالبًا المحتوى ضعيف أو قصير' => 'Google crawled the page but did not index it (usually thin content)',
    'زوّد المحتوى بمعلومات حقيقية: برنامج اليوم، اللي شامله السعر، أسئلة شائعة، صور أصلية، ولينك للصفحة من الرئيسية وصفحات الرحلات القريبة. بعدها اطلب فهرسة.' => 'Add real details: day plan, inclusions, FAQs, original photos, and link to it from the home and related trip pages. Then request indexing.',
    'زوّد المحتوى بمعلومات حقيقية: برنامج اليوم، اللي شامله السعر، أسئلة شائعة، صور أصلية، ولينك للصفحة من الرئيسية وصفحات الرحلات القريبة. بعدها اطلب فهرسة' => 'Add real details: day plan, inclusions, FAQs, original photos, and link to it from the home and related trip pages. Then request indexing',
    'جوجل عارف الصفحة بس لسه مازارهاش' => 'Google knows the page but has not crawled it yet',
    'حط لينك للصفحة من الرئيسية والقوائم، واتأكد إنها في الـ sitemap، واطلب فهرسة من Search Console.' => 'Link to it from the home page and menus, keep it in the sitemap and request indexing in Search Console.',
    'حط لينك للصفحة من الرئيسية والقوائم، واتأكد إنها في الـ sitemap، واطلب فهرسة من' => 'Link to it from the home page and menus, keep it in the sitemap and request indexing in Search Console',
    'جوجل مايعرفش الصفحة دي خالص' => 'Google does not know this page at all',
    'ضيفها للـ sitemap وحط لينك ليها من صفحات تانية، وبعدين من Search Console > فحص الرابط اطلب فهرسة.' => 'Add it to the sitemap, link to it from other pages, then request indexing in Search Console > URL Inspection.',
    'ضيفها للـ sitemap وحط لينك ليها من صفحات تانية، وبعدين من Search Console > فحص الرابط اطلب فهرسة' => 'Add it to the sitemap, link to it from other pages, then request indexing in Search Console > URL Inspection',
    'اتأكد إن الصفحة بتفتح من غير تسجيل دخول وبترجع 200، وإن الاستضافة مش بتمنع زاحف جوجل.' => 'Make sure the page opens without login, returns 200 and the host does not block Googlebot.',
    'اتأكد إن الصفحة بتفتح من غير تسجيل دخول وبترجع 200، وإن الاستضافة مش بتمنع زاحف جوجل' => 'Make sure the page opens without login, returns 200 and the host does not block Googlebot',
    'افتح Search Console > فحص الرابط للصفحة دي وشوف السبب، واطلب فهرسة بعد التصليح.' => 'Open Search Console > URL Inspection for this page, fix the reason and request indexing.',
