    'المنصة بتعالج ظهورها في جوجل' => 'Being fixed automatically',
    'المنصة بعتت خريطة الموقع لجوجل تاني، وبتضيف روابط داخلية للصفحة دي من صفحات موقعك المرتبطة بيها. هتتفحص حالتها في جوجل تاني في الدورة الجاية، ومش مطلوب منك أي حاجة.' => 'The platform resubmitted your sitemap to Google and is adding internal links to this page from related pages. Its Google status is rechecked next cycle; nothing is needed from you.',
    'المنصة بعتت خريطة الموقع لجوجل تاني، وبتضيف روابط داخلية للصفحة دي من صفحات موقعك المرتبطة بيها. هتتفحص حالتها في جوجل تاني في الدورة الجاية، ومش مطلوب منك أي حاجة' => 'The platform resubmitted your sitemap to Google and is adding internal links to this page from related pages. Its Google status is rechecked next cycle; nothing is needed from you',
