    'مبني على الإجابات المحفوظة من قياس ظهورك في الذكاء الصناعي. مفيش طلبات جديدة لمحركات الـAI في الصفحة دي، ما عدا تحليل الانطباع لما تضغط عليه.' => 'Built from the answers saved by your AI visibility checks. This page sends no new requests to AI engines, except sentiment analysis when you click it.',
