    'التحليل بيقرا بس الجمل اللي فيها اسم شركتك، وبيستهلك من رصيد أدوات الـAI. الإجابة بتتحلل مرة واحدة بس.' => 'The analysis reads only the sentences that name your company and uses your AI tools balance. Each answer is analyzed once.',
    'التحليل بيقرا بس الجمل اللي فيها اسم شركتك، وبيستهلك من رصيد أدوات الـAI. الإجابة بتتحلل مرة واحدة بس' => 'The analysis reads only the sentences that name your company and uses your AI tools balance. Each answer is analyzed once',
