    'أكتر الصفحات زيارة من البوتات' => 'Pages crawlers visit most',
    '١. ارفع سجل الزيارات (access log)' => '1. Upload your access log',
    '١. ارفع سجل الزيارات' => '1. Upload your access log',
    'نزّل سجل Apache أو Nginx من الاستضافة (بصيغة combined، عادي أو مضغوط .gz لحد 25 ميجا). لو رفعت نفس الأيام تاني، الأرقام القديمة بتتبدل بالجديدة ومش بتتكرر.' => 'Download your Apache or Nginx log from your hosting (combined format, plain or .gz, up to 25 MB). Uploading the same days again replaces their numbers instead of adding to them.',
    'نزّل سجل Apache أو Nginx من الاستضافة (بصيغة combined، عادي أو مضغوط .gz لحد 25 ميجا). لو رفعت نفس الأيام تاني، الأرقام القديمة بتتبدل بالجديدة ومش بتتكرر' => 'Download your Apache or Nginx log from your hosting (combined format, plain or .gz, up to 25 MB). Uploading the same days again replaces their numbers instead of adding to them',
    'رفع وتحليل' => 'Upload and analyze',
    '٢. أو تابع الزيارات أول بأول بكود صغير على موقعك' => '2. Or track visits live with a small snippet on your site',
    'لو موقعك PHP أو WordPress، حط الكود ده في أول ملف index.php (أو في mu-plugin). الكود بيشتغل بس لما بوت AI يزور الموقع، وبيبعت للمنصة مسار الصفحة ونوع البوت، وبيستنى أقل من ثانية بحد أقصى.' => 'If your site runs PHP or WordPress, put this snippet at the top of index.php (or in a mu-plugin). It runs only when an AI crawler visits, sends the page path and crawler name, and waits less than a second.',
    'لو موقعك PHP أو WordPress، حط الكود ده في أول ملف index.php (أو في mu-plugin). الكود بيشتغل بس لما بوت AI يزور الموقع، وبيبعت للمنصة مسار الصفحة ونوع البوت، وبيستنى أقل من ثانية بحد أقصى' => 'If your site runs PHP or WordPress, put this snippet at the top of index.php (or in a mu-plugin). It runs only when an AI crawler visits, sends the page path and crawler name, and waits less than a second',
