    'حفظ' => 'Save',
    'Claude بيستخدم مفتاح Anthropic المحفوظ في إعدادات الربط بتاعة المنصة، وبيمشي على نفس الميزانية الشهرية وحصص الباقات اللي بيمشي عليها ChatGPT وGemini وPerplexity. التكلفة التقريبية للسؤال الواحد على claude-opus-5-5 من 0.05 لـ 0.12 دولار.' => 'Claude uses the Anthropic key saved in the platform connection settings and follows the same monthly budget and plan quotas as ChatGPT, Gemini and Perplexity. One question on claude-opus-5-5 costs about $0.05 to $0.12.',
    'Claude بيستخدم مفتاح Anthropic المحفوظ في إعدادات الربط بتاعة المنصة، وبيمشي على نفس الميزانية الشهرية وحصص الباقات اللي بيمشي عليها ChatGPT وGemini وPerplexity. التكلفة التقريبية للسؤال الواحد على claude-opus-5-5 من 0.05 لـ 0.12 دولار' => 'Claude uses the Anthropic key saved in the platform connection settings and follows the same monthly budget and plan quotas as ChatGPT, Gemini and Perplexity. One question on claude-opus-5-5 costs about $0.05 to $0.12',
