    'أول ما حد يكتب "بكام؟" أو "عايز أحجز" تحت منشورك، المنصة تبعتله رسالة خاصة (ماسنجر/دايركت) بالتفاصيل ورابط الحجز، وترد علنيًا إنها بعتتله. ده بيحوّل التعليقات لحجوزات وانت نايم.' => 'When someone comments "how much?" or "I want to book", the platform sends them a private message (Messenger/Direct) with details and your booking link, and replies publicly that it did. Comments turn into bookings while you sleep.',
    'أول ما حد يكتب "بكام؟" أو "عايز أحجز" تحت منشورك، المنصة تبعتله رسالة خاصة (ماسنجر/دايركت) بالتفاصيل ورابط الحجز، وترد علنيًا إنها بعتتله. ده بيحوّل التعليقات لحجوزات وانت نايم' => 'When someone comments "how much?" or "I want to book", the platform sends them a private message (Messenger/Direct) with details and your booking link, and replies publicly that it did. Comments turn into bookings while you sleep',
