    'الرد العلني القصير' => 'Short public reply',
    'محتاج صلاحية رسائل الصفحة من Meta (pages_messaging). Meta بتسمح برسالة خاصة واحدة لكل تعليق خلال 7 أيام.' => 'Requires Meta page messaging permission (pages_messaging). Meta allows one private message per comment within 7 days.',
    'محتاج صلاحية رسائل الصفحة من Meta (pages_messaging). Meta بتسمح برسالة خاصة واحدة لكل تعليق خلال 7 أيام' => 'Requires Meta page messaging permission (pages_messaging). Meta allows one private message per comment within 7 days',
    'مراقبة المنافسين على إنستجرام' => 'Instagram competitor monitoring',
    'ضيف لحد 5 حسابات بيزنس منافسة. كل يوم بنجيب متابعينهم ومعدل نشرهم ومتوسط تفاعلهم وأنجح منشوراتهم وهاشتاجاتهم، ونقارنهم بحسابك.' => 'Add up to 5 competing business accounts. Every day we fetch their followers, posting rhythm, average engagement, top posts and hashtags, and compare them to your account.',
    'ضيف لحد 5 حسابات بيزنس منافسة. كل يوم بنجيب متابعينهم ومعدل نشرهم ومتوسط تفاعلهم وأنجح منشوراتهم وهاشتاجاتهم، ونقارنهم بحسابك' => 'Add up to 5 competing business accounts. Every day we fetch their followers, posting rhythm, average engagement, top posts and hashtags, and compare them to your account',
    'اسم الحساب أو الرابط - مثال: @competitor_tours' => 'Username or link — e.g. @competitor_tours',
