    'الخطة الشهرية بيجهزها ويعتمدها صاحب الحساب. تقدر تشوف منشوراتها المجدولة في تبويب «المنشورات والتقويم».' => 'The monthly plan is prepared and approved by the account owner. You can see its scheduled posts in the "Posts & calendar" tab.',
    'الخطة الشهرية بيجهزها ويعتمدها صاحب الحساب. تقدر تشوف منشوراتها المجدولة في تبويب «المنشورات والتقويم' => 'The monthly plan is prepared and approved by the account owner. You can see its scheduled posts in the "Posts & calendar" tab',
    'موافقة العميل على الخطة' => 'Client approval',
    'ابعت لصاحب الشركة رابط خاص يشوف فيه منشورات الشهر بالصور والنصوص والمواعيد، ويكتب ملاحظاته أو يعتمد الخطة من غير ما يسجّل دخول. كل رد بيوصلك إشعار.' => 'Send the business owner a private link to review the month\'s posts with images, captions and dates, leave comments or approve — no login needed. You get notified on every response.',
    'ابعت لصاحب الشركة رابط خاص يشوف فيه منشورات الشهر بالصور والنصوص والمواعيد، ويكتب ملاحظاته أو يعتمد الخطة من غير ما يسجّل دخول. كل رد بيوصلك إشعار' => 'Send the business owner a private link to review the month\'s posts with images, captions and dates, leave comments or approve — no login needed. You get notified on every response',
