    'اختار الصفحات اللي هتشتغل عليها: الصفحة الموقوفة بتختفي من النشر وما بتتحسبش من حسابات باقتك، وتقدر تشغّلها تاني في أي وقت.' => 'Choose the pages you work with: a paused page is hidden from publishing and does not count toward your plan, and you can turn it back on any time.',
