    'ليه صندوق التعليقات أو أول تعليق مش شغالين؟' => 'Why don\'t the comments inbox or first comment work?',
    'قراءة التعليقات والرد عليها محتاجين صلاحيات إضافية من Meta: pages_read_user_content و pages_manage_engagement (فيسبوك) و instagram_manage_comments (إنستجرام). مدير المنصة يضيفهم في إعداد META_SOCIAL_EXTRA_SCOPES ويطلب موافقة Meta عليهم (App Review)، وبعدها اربط فيسبوك وإنستجرام تاني ووافق على كل الصلاحيات.' => 'Reading and replying to comments needs extra Meta permissions: pages_read_user_content and pages_manage_engagement (Facebook) and instagram_manage_comments (Instagram). The platform admin adds them to META_SOCIAL_EXTRA_SCOPES and requests Meta App Review; then reconnect Facebook & Instagram and accept all permissions.',
    'قراءة التعليقات والرد عليها محتاجين صلاحيات إضافية من Meta: pages_read_user_content و pages_manage_engagement (فيسبوك) و instagram_manage_comments (إنستجرام). مدير المنصة يضيفهم في إعداد META_SOCIAL_EXTRA_SCOPES ويطلب موافقة Meta عليهم (App Review)، وبعدها اربط فيسبوك وإنستجرام تاني ووافق على كل الصلاحيات' => 'Reading and replying to comments needs extra Meta permissions: pages_read_user_content and pages_manage_engagement (Facebook) and instagram_manage_comments (Instagram). The platform admin adds them to META_SOCIAL_EXTRA_SCOPES and requests Meta App Review; then reconnect Facebook & Instagram and accept all permissions',
