    'لو موقعك WordPress، نزّل Tourfecto Connect الخاصة بهذا الموقع. تشمل SEO ومحرر الصفحات ودعم نصوص Traveler 3.4 وقياس WooCommerce الاختياري. تعديل المحتوى يحتاج ربط حساب WordPress بصلاحياته.' => 'Install this site’s Tourfecto Connect: SEO, page editor, Traveler 3.4 text and optional WooCommerce measurement. Content editing requires authorized WordPress credentials.',
    'لو موقعك WordPress، نزّل Tourfecto Connect الخاصة بهذا الموقع. تشمل SEO ومحرر الصفحات ودعم نصوص Traveler 3.4 وقياس WooCommerce الاختياري. تعديل المحتوى يحتاج ربط حساب WordPress بصلاحياته' => 'Install this site’s Tourfecto Connect: SEO, page editor, Traveler 3.4 text and optional WooCommerce measurement. Content editing requires authorized WordPress credentials',
