    'بيانات FTP بتتستخدم مرة واحدة ومش بتتحفظ. بناخد نسخة احتياطية قبل أي تعديل، ولو أي حاجة مش مظبوطة بنرجّع موقعك زي ما كان. بيانات FTP هتلاقيها في لوحة الاستضافة (aaPanel / cPanel) في قسم FTP.' => 'FTP details are used once and never stored. We back up before any change and restore your site if anything is off. Find FTP details in your hosting panel (aaPanel / cPanel) under FTP.',
    'بيانات FTP بتتستخدم مرة واحدة ومش بتتحفظ. بناخد نسخة احتياطية قبل أي تعديل، ولو أي حاجة مش مظبوطة بنرجّع موقعك زي ما كان. بيانات FTP هتلاقيها في لوحة الاستضافة (aaPanel / cPanel) في قسم' => 'FTP details are used once and never stored. We back up before any change and restore your site if anything is off. Find FTP details in your hosting panel (aaPanel / cPanel) under FTP',
