    'افتح رابط موقعك وفي آخره ‎?tf_check=1‎ (مثال: yoursite.com/?tf_check=1) - لازم تظهر جملة "Tourfecto Connect v4".' => 'Open your site URL ending with ?tf_check=1 (e.g. yoursite.com/?tf_check=1) - it must show "Tourfecto Connect v4".',
