    'صلاحيات المحتوى والنشر' => 'Content & publishing permissions',
    'لمواقع WordPress: الإضافة الموحدة لا تمنح صلاحيات الحساب، اربطه لتعديل المحتوى أو نشر محتوى جديد بعد الاعتماد. مواقع PHP بتنشر المقالات من خلال ملف الربط ومش محتاجة الخطوة دي.' => 'WordPress sites: the unified plugin does not grant account permissions; connect an account to edit or publish approved content. PHP sites publish articles through the connector file and can skip this step.',
    'لمواقع WordPress: الإضافة الموحدة لا تمنح صلاحيات الحساب، اربطه لتعديل المحتوى أو نشر محتوى جديد بعد الاعتماد. مواقع PHP بتنشر المقالات من خلال ملف الربط ومش محتاجة الخطوة دي' => 'WordPress sites: the unified plugin does not grant account permissions; connect an account to edit or publish approved content. PHP sites publish articles through the connector file and can skip this step',
