    'لو سبته صفر، مش هيتخصم منك أي حاجة زيادة عن باقتك' => 'Leave it at 0 and nothing beyond your plan is ever charged',
    'الطيار الآلي (مُوصى به): المنصة تفحص موقعك كل أسبوع وتنفذ التعديلات الآمنة لوحدها (العناوين، الأوصاف، Schema، الروابط الداخلية، المقالات) في حدود الميزانية دي. أي تعديل فيه معلومة جديدة عن شركتك بيستنى موافقتك، وكل تعديل تقدر ترجع فيه بضغطة.' => 'Autopilot (recommended): the platform checks your site every week and applies safe changes on its own (titles, descriptions, schema, internal links, articles) within this budget. Anything stating a new fact about your company waits for your approval, and every change can be undone in one click.',
    'الطيار الآلي (مُوصى به): المنصة تفحص موقعك كل أسبوع وتنفذ التعديلات الآمنة لوحدها (العناوين، الأوصاف، Schema، الروابط الداخلية، المقالات) في حدود الميزانية دي. أي تعديل فيه معلومة جديدة عن شركتك بيستنى موافقتك، وكل تعديل تقدر ترجع فيه بضغطة' => 'Autopilot (recommended): the platform checks your site every week and applies safe changes on its own (titles, descriptions, schema, internal links, articles) within this budget. Anything stating a new fact about your company waits for your approval, and every change can be undone in one click',
    'المعلومات صحيحة وأوافق على حدود وتكلفة العمل الموضحة.' => 'These facts are correct and I accept the displayed work and cost limits.',
