    'تجهيز المقال ممكن يحتاج بحث كلمات واحد زيادة. لو سبته صفر هنستخدم باقتك بس، ولو مش كفاية الخطة هتكمل من غير المقال.' => 'The article may need one extra keyword lookup. At 0 we use your plan only; if that is not enough the plan continues without the article.',
