    'معلومة تجارية محتاجة تأكيد' => 'Business claim needs confirmation',
    'العبارات دي مش مثبتة بنفس الصياغة والنطاق في معلومات نشاطك المؤكدة. لو غير دقيقة احذفها من الاقتراح واحفظه. لو صحيحة حدّث معلومات نشاطك وراجع الخطة وفق النسخة الجديدة.' => 'These statements are not recorded with the same wording and scope in your confirmed business facts. Remove inaccurate statements and save the proposal, or update your business facts and review a plan using the new revision.',
    'العبارات دي مش مثبتة بنفس الصياغة والنطاق في معلومات نشاطك المؤكدة. لو غير دقيقة احذفها من الاقتراح واحفظه. لو صحيحة حدّث معلومات نشاطك وراجع الخطة وفق النسخة الجديدة' => 'These statements are not recorded with the same wording and scope in your confirmed business facts. Remove inaccurate statements and save the proposal, or update your business facts and review a plan using the new revision',
    'لو المحتوى منشور بالفعل، راجعه في موقعك الأصلي. التحقق التقني وسجل النشر محفوظان؛ ظهور النص لا يؤكد صحة السياسة.' => 'For already published content, review it on your original site. Technical verification and publication history are retained; seeing the text does not confirm its factual accuracy.',
