    'مراجعة وتصحيح المقال المنشور' => 'Review and correct published article',
    'الحفظ سيحدّث نفس الرابط. النسخة السابقة وصورتها وروابطها تظل محفوظة في السجل. راجع المعاينة ثم أكد الحفظ؛ التحقق من الصفحة يتم بعد تحديث كاش الربط.' => 'Saving updates the same URL and retains the previous version, image and link settings in history. Review the preview and confirm saving; public verification follows the connector cache refresh.',
    'الحفظ سيحدّث نفس الرابط. النسخة السابقة وصورتها وروابطها تظل محفوظة في السجل. راجع المعاينة ثم أكد الحفظ؛ التحقق من الصفحة يتم بعد تحديث كاش الربط' => 'Saving updates the same URL and retains the previous version, image and link settings in history. Review the preview and confirm saving; public verification follows the connector cache refresh',
    'النص المصحح' => 'Corrected article text',
