    'المطلوب من المطور: إضافة H1 واضح يصف هذه الصفحة. بعد التنفيذ، سجّل ما تم واضغط إعادة الفحص' => 'Developer task: add a descriptive H1, then record completion and recheck',
    'أكد أولًا أن الصفحة مطلوب ظهورها في البحث. لو نعم، اطلب من المطور إزالة noindex غير المقصود، ثم أعد الفحص. لا نغيّر هذا القرار تلقائيًا.' => 'Confirm the page should be searchable. Ask the developer to remove unintended noindex, then recheck.',
    'أكد أولًا أن الصفحة مطلوب ظهورها في البحث. لو نعم، اطلب من المطور إزالة noindex غير المقصود، ثم أعد الفحص. لا نغيّر هذا القرار تلقائيًا' => 'Confirm the page should be searchable. Ask the developer to remove unintended noindex, then recheck',
    'WordPress: نزّل الإضافة الخاصة بهذا الموقع وفعّلها. موقع PHP مبرمج خاص: نزّل ملف الربط tourfecto-connect.php وارفعه للمجلد الرئيسي وضيف سطر require في أول ملف مشترك بين الصفحات. بعدها امسح كاش الصفحة واضغط اختبار الربط.' => 'WordPress: install and activate this site’s plugin. Custom PHP site: upload tourfecto-connect.php to the root and require it at the top of a shared file. Then clear the page cache and test the connection.',
    'WordPress: نزّل الإضافة الخاصة بهذا الموقع وفعّلها. موقع PHP مبرمج خاص: نزّل ملف الربط tourfecto-connect.php وارفعه للمجلد الرئيسي وضيف سطر require في أول ملف مشترك بين الصفحات. بعدها امسح كاش الصفحة واضغط اختبار الربط' => 'WordPress: install and activate this site’s plugin. Custom PHP site: upload tourfecto-connect.php to the root and require it at the top of a shared file. Then clear the page cache and test the connection',
    'اضغط ربط Search Console، اختر حساب Google وبيانات هذا الموقع، ثم اضغط اختبار الربط. بعدها تقدر الخدمة تقيس الظهور والنقرات الفعلية.' => 'Connect Search Console, select this site’s property, then test real access.',
