    'ماذا يحدث عند الحفظ؟' => 'What happens when I save?',
    'تُضاف الرحلة إلى كتالوج حسابك وتُربط بهذا الموقع فقط. لا يتغير موقعك ولا يُنشأ حجز أو دفع. استيراد الرحلات لا يستورد مدفوعات نظام خارجي. السعر أو العملة الناقصان يحتاجان تأكيدك، ولكل رحلة مستوردة رابط صفحة مستقل.' => 'The product is added to your account catalog and mapped to this website. Your site is not changed and no booking or payment is created. External payments are not imported. Missing prices/currencies require confirmation; use one product page per import.',
    'تُضاف الرحلة إلى كتالوج حسابك وتُربط بهذا الموقع فقط. لا يتغير موقعك ولا يُنشأ حجز أو دفع. استيراد الرحلات لا يستورد مدفوعات نظام خارجي. السعر أو العملة الناقصان يحتاجان تأكيدك، ولكل رحلة مستوردة رابط صفحة مستقل' => 'The product is added to your account catalog and mapped to this website. Your site is not changed and no booking or payment is created. External payments are not imported. Missing prices/currencies require confirmation; use one product page per import',
