    'قياس حجوزات المنصة غير متاح في هذه النسخة. راجع الدعم لتفعيله؛ قياس البحث والزيارات يستمر بشكل مستقل.' => 'Platform booking measurement is unavailable in this installation. Contact support to enable it; search and traffic measurement continue separately.',
    'قياس حجوزات المنصة غير متاح في هذه النسخة. راجع الدعم لتفعيله؛ قياس البحث والزيارات يستمر بشكل مستقل' => 'Platform booking measurement is unavailable in this installation. Contact support to enable it; search and traffic measurement continue separately',
    'اختَر الرحلات الخاصة بالموقع أولًا. لم نعتبر عدم الربط صفر حجوزات، ولن ننسب مبيعات مواقعك الأخرى لهذا الموقع.' => 'Choose this site’s products first. An unconfigured mapping is not zero bookings, and other sites’ sales are not assigned here.',
    'اختَر الرحلات الخاصة بالموقع أولًا. لم نعتبر عدم الربط صفر حجوزات، ولن ننسب مبيعات مواقعك الأخرى لهذا الموقع' => 'Choose this site’s products first. An unconfigured mapping is not zero bookings, and other sites’ sales are not assigned here',
