    'مقارنة حسب تاريخ إنشاء الحجز بتوقيت UTC. هذه المبيعات لا تُنسب لصفحة دخول أو قناة' => 'Cohorts use booking creation dates in UTC. These figures are not assigned to a landing page or SEO traffic channel',
