    'كيف تُحسب الأرقام؟' => 'How are these figures calculated?',
    'تُستخدم قيم الدفعات الحالية بعد الاستردادات الناجحة، ولا تُعد موافقة الحجز اليدوية دفعًا. لا نفترض سعر تحويل للعملات، ولا نحسب المدفوعات اليدوية أو المحاولات غير المكتملة. هذه ليست حركة نقدية تاريخية أو إثباتًا أن SEO سبب المبيعات.' => 'Values use current captured payments net of successful refunds. Manual booking confirmation alone is not payment. No exchange rate is assumed; manual payments and incomplete attempts are excluded. Values are not historical cash flow or proof that SEO caused sales.',
    'تُستخدم قيم الدفعات الحالية بعد الاستردادات الناجحة، ولا تُعد موافقة الحجز اليدوية دفعًا. لا نفترض سعر تحويل للعملات، ولا نحسب المدفوعات اليدوية أو المحاولات غير المكتملة. هذه ليست حركة نقدية تاريخية أو إثباتًا أن SEO سبب المبيعات' => 'Values use current captured payments net of successful refunds. Manual booking confirmation alone is not payment. No exchange rate is assumed; manual payments and incomplete attempts are excluded. Values are not historical cash flow or proof that SEO caused sales',
    'مرتبط بموقع آخر' => 'Assigned to another site',
    'لا توجد رحلات مطابقة. استخدم «إضافة رحلة أو استيراد من موقعي» أدناه.' => 'No matching products. Use “Add a product or import from my site” below.',
    'لا توجد رحلات مطابقة. استخدم «إضافة رحلة أو استيراد من موقعي» أدناه' => 'No matching products. Use “Add a product or import from my site” below',
