    'الرحلات المختارة' => 'Selected products',
    'صفحات تحت المتابعة' => 'Pages being monitored',
    'مقارنات مجدولة أو مجمعة' => 'Scheduled or collected comparisons',
    'مقارنات جُمعت' => 'Collected comparisons',
    'مقارنات تحتاج مراجعة' => 'Comparisons needing review',
    'المنصة تتابع نتيجة التعديلات' => 'The platform follows edit outcomes',
    'التعديلات المنفذة تُتابع تلقائيًا بفترات 7 و14 و28 يومًا، ولا تحتاج إنشاء مقارنة يدوية لكل تعديل.' => 'Applied edits are followed automatically over 7, 14 and 28 days; you do not need to create a manual comparison for each edit.',
    'التعديلات المنفذة تُتابع تلقائيًا بفترات 7 و14 و28 يومًا، ولا تحتاج إنشاء مقارنة يدوية لكل تعديل' => 'Applied edits are followed automatically over 7, 14 and 28 days; you do not need to create a manual comparison for each edit',
    'لم تُجمع مقارنة بعد؛ ننتظر اكتمال الفترات ووصول بيانات المصادر. هذه ليست نتيجة صفر زيارات أو حجوزات.' => 'No comparison collected yet; full windows and source data are still needed. This is not a zero traffic or bookings result.',
    'لم تُجمع مقارنة بعد؛ ننتظر اكتمال الفترات ووصول بيانات المصادر. هذه ليست نتيجة صفر زيارات أو حجوزات' => 'No comparison collected yet; full windows and source data are still needed. This is not a zero traffic or bookings result',
    'أقرب موعد مجدول لجمع المقارنة:' => 'Earliest scheduled collection:',
    'أقرب موعد مجدول لجمع المقارنة' => 'Earliest scheduled collection',
    'الملخص يشمل السجل كله؛ تفاصيل أحدث 20 مقارنة تظهر أدناه.' => 'The summary covers all records; the latest 20 comparisons are detailed below.',
    'الملخص يشمل السجل كله؛ تفاصيل أحدث 20 مقارنة تظهر أدناه' => 'The summary covers all records; the latest 20 comparisons are detailed below',
    'حالة الربط المحفوظة ليست إثبات وصول البيانات. القياس يراجع المصدر عند الجمع، وأحداث GA4 لا تُعد حجوزات مدفوعة مؤكدة.' => 'A saved connection does not establish data access. Collection checks the provider; GA4 events are not confirmed paid bookings.',
    'حالة الربط المحفوظة ليست إثبات وصول البيانات. القياس يراجع المصدر عند الجمع، وأحداث GA4 لا تُعد حجوزات مدفوعة مؤكدة' => 'A saved connection does not establish data access. Collection checks the provider; GA4 events are not confirmed paid bookings',
    'استقبال طلبات WooCommerce خدمة مستقلة. حجوزات نظام المنصة تظهر أعلاه بعد ربط الرحلات؛ أنظمة الحجز الخارجية الخاصة تحتاج ربطًا مستقلًا لاستقبال مدفوعاتها.' => 'WooCommerce receipts are a separate source. Platform booking sales appear above after mapping products; a custom external booking system needs its own receipt integration.',
    'استقبال طلبات WooCommerce خدمة مستقلة. حجوزات نظام المنصة تظهر أعلاه بعد ربط الرحلات؛ أنظمة الحجز الخارجية الخاصة تحتاج ربطًا مستقلًا لاستقبال مدفوعاتها' => 'WooCommerce receipts are a separate source. Platform booking sales appear above after mapping products; a custom external booking system needs its own receipt integration',
    'ربط الطلبات هنا خاص بـ WooCommerce وإضافة Tourfecto Measure. فعّله فقط بعد تثبيت الإضافة؛ لا تُستورد الطلبات القديمة، والطلبات بلا صفحة دخول لا تُنسب لصفحة محددة.' => 'This receipt connection requires WooCommerce and Tourfecto Measure. Enable it after installing the plugin. No historical backfill; unknown landing pages remain unattributed.',
    'ربط الطلبات هنا خاص بـ WooCommerce وإضافة Tourfecto Measure. فعّله فقط بعد تثبيت الإضافة؛ لا تُستورد الطلبات القديمة، والطلبات بلا صفحة دخول لا تُنسب لصفحة محددة' => 'This receipt connection requires WooCommerce and Tourfecto Measure. Enable it after installing the plugin. No historical backfill; unknown landing pages remain unattributed',
    'الربط التلقائي المتاح هنا خاص بـ WooCommerce. المواقع المبرمجة خصيصًا تحتاج ربط الحجوزات بنظامها؛ يمكن متابعة GSC وGA4 الآن، ووجود Analytics لا يثبت استقبال حجوزات مدفوعة.' => 'Automatic receipt setup here is for WooCommerce. A custom site needs its booking system integrated; GSC and GA4 measurement can continue, and Analytics does not establish paid-order receipt coverage.',
    'الربط التلقائي المتاح هنا خاص بـ WooCommerce. المواقع المبرمجة خصيصًا تحتاج ربط الحجوزات بنظامها؛ يمكن متابعة GSC وGA4 الآن، ووجود Analytics لا يثبت استقبال حجوزات مدفوعة' => 'Automatic receipt setup here is for WooCommerce. A custom site needs its booking system integrated; GSC and GA4 measurement can continue, and Analytics does not establish paid-order receipt coverage',
    'الأرقام المعروضة حسب مصادرها؛ القيم غير المتاحة لا تتحول لصفر.' => 'Metrics retain their source; unavailable values are never turned into zero.',
    'الأرقام المعروضة حسب مصادرها؛ القيم غير المتاحة لا تتحول لصفر' => 'Metrics retain their source; unavailable values are never turned into zero',
