    'اربطه بالطريقة دي عشان يفضل شغال على موبايلك وعلى المنصة مع بعض: هتكمّل ترد من الموبايل عادي، وكل الرسايل هتظهر هنا في الوارد. Meta بتطلب تطبيق واتساب بزنس محدّث، وهيظهرلك كود QR تمسحه من التطبيق.' => 'Connect it this way to keep using it on your phone and on the platform together: keep replying from the phone as usual, and every message also shows in the inbox here. Meta needs an up-to-date WhatsApp Business app and will show a QR code to scan from it.',
    'اربطه بالطريقة دي عشان يفضل شغال على موبايلك وعلى المنصة مع بعض: هتكمّل ترد من الموبايل عادي، وكل الرسايل هتظهر هنا في الوارد. Meta بتطلب تطبيق واتساب بزنس محدّث، وهيظهرلك كود QR تمسحه من التطبيق' => 'Connect it this way to keep using it on your phone and on the platform together: keep replying from the phone as usual, and every message also shows in the inbox here. Meta needs an up-to-date WhatsApp Business app and will show a QR code to scan from it',
    'اربط رقم واتساب بزنس اللي على موبايلي' => 'Connect my WhatsApp Business app number',
    'ممكن Meta تطلب وسيلة دفع وانت بتربط. ده مش إجباري للربط، وMeta بتحاسب بس على القوالب والرسايل التسويقية. الرد على عملاء كلموك خلال 24 ساعة ببلاش.' => 'Meta may ask for a payment method while connecting. It is not required to connect; Meta only charges for templates and marketing messages. Replying to customers within 24 hours is free.',
    'ممكن Meta تطلب وسيلة دفع وانت بتربط. ده مش إجباري للربط، وMeta بتحاسب بس على القوالب والرسايل التسويقية. الرد على عملاء كلموك خلال 24 ساعة ببلاش' => 'Meta may ask for a payment method while connecting. It is not required to connect; Meta only charges for templates and marketing messages. Replying to customers within 24 hours is free',
    'الربط الرسمي بتسجيل دخول فيسبوك هيتفعّل قريب. دلوقتي تقدر تربط رقمك بمسح كود QR تحت.' => 'Official connection with Facebook sign-in is coming soon. For now, connect your number by scanning the QR code below.',
