    'تتابع من الموبايل إزاي: اضغط «تثبيت التطبيق» تحت وافتح الوارد منه زي أي تطبيق. ولو عايز نفس الرقم يشتغل على تطبيق واتساب بزنس كمان: افصل الربط، ونزّل الرقم على تطبيق واتساب بزنس، واربطه تاني من زرار «اربط رقم واتساب بزنس اللي على موبايلي».' => 'Follow from your phone: tap “Install app” below and open the inbox from it like any app. To also use this number in the WhatsApp Business app: disconnect, set the number up in the WhatsApp Business app, then reconnect with “Connect my WhatsApp Business app number”.',
